OLD=D/'VTR_diffeq_p1_input_01';P=D/'VTR_diffeq_p1_input_02';B=D/'diffeq_p1_native_import_probe_02';U=D/'VTR_diffeq_p1_input_03'
def main():
 assert not U.exists();original=read(OLD/'queue/completion.json');prior=read(P/'queue/completion.json');place=read(P/'place_01/execution_completion.json');probe=read(B/'completion.json');cap=read(OLD/'capacity_selection.json');plan=read(P/'registration.json');assert not original['passed'] and not prior['passed'] and place['passed'] and probe['execution_ended'] and probe['command_returncode']==1 and not probe['route_quality_admitted'];assert all(sha(p)==h for p,h in plan['source_sha256'].items());assert all(sha(p)==h for p,h in probe['source_sha256'].items());assert sha(B/'measurement/stdout.log')==probe['actual_stdout_sha256']
