 files=[Path(__file__).resolve(),OLD/'registration.json',OLD/'queue/completion.json',OLD/'pack_01/registration.json',OLD/'pack_01/execution_completion.json',base,OLD/'capacity_selection.json',P/'registration.json',P/'queue/completion.json',P/'place_01/registration.json',P/'place_01/execution_completion.json',P/'place_01/triton_evidence/manifest.json',P/'place_01/measurement/stdout.log',B/'registration.json',B/'completion.json',B/'measurement/stdout.log',packed_reader,coord_reader];bound={str(p):sha(p) for p in files};U.mkdir();(U/'place_01').mkdir();shutil.copyfile(OLD/'capacity_selection.json',U/'capacity_selection.json');shutil.copyfile(P/'place_01/registration.json',U/'place_01/registration.json')
 write(U/'registration.json',dict(registered_at=datetime.now(timezone.utc).isoformat(),new_scope='New independent physical input; not a continuation of a routed stage.',prior_failed_attempts_preserved=[str(OLD/'queue/completion.json'),str(P/'queue/completion.json')],new_native_route_queries=0,source_sha256=bound))
 write(U/'packing_provenance.json',dict(format='derived_upstream_receipts_v1',status='completed',command=command,outputs={'packed.net':physical['packed'],'placed.place':physical['placement']},source_sha256={**bound,str(U/'registration.json'):sha(U/'registration.json')},historical_manifest_rewritten=False,qualification='P1 produced a different actual clustering than the earlier census, with equal atomic name/type multiset. Frozen native VPR imported the actual BLIF/packed/placement and passed placement consistency; intentionally missing routing file caused return code 1. This is input preparation, not FULL/STA/physical route admission. Original P1 command uses default constant merging; route must match it.'))
 write(U/'completion.json',dict(passed=True,status='actual_P1_physical_input_prepared_native_import_observed',physical_files=physical,actual_packed=summary,actual_layout=dict(placed_blocks=len(coords),coordinate_semantic_sha256=hashlib.sha256(json.dumps([[n,*coords[n]] for n in sorted(coords)],separators=(',',':')).encode()).hexdigest(),layer_block_counts=dict(Counter(v[3] for v in coords.values()))),costs=[dict(stage='reused_original_census_pack',complete_command_seconds=read(OLD/'pack_01/execution_completion.json')['complete_upstream_command_seconds']),dict(stage='prior_P1_SDC_failure',complete_command_seconds=read(OLD/'place_01/execution_completion.json')['complete_upstream_command_seconds']),dict(stage='actual_P1_pack_place',complete_command_seconds=place['complete_upstream_command_seconds']),dict(stage='native_import_default_merge_no_route',complete_command_seconds=probe['complete_command_seconds'])],source_sha256={**bound,str(U/'registration.json'):sha(U/'registration.json'),str(U/'packing_provenance.json'):sha(U/'packing_provenance.json')},route_quality_admitted=False,route_queries=0,explicit_SDC=True,application_timing_claim=False,qualification='Different public circuit and actual P1 packing/layout, same architecture family. Initial route and original FULL/STA/vector/physical and pair gates remain mandatory. The two older input-preparation failures remain unchanged.'))
